    // Return a Pair with a and b swapped
}

solutionCode:
fun <T> swap(a: T, b: T): Pair<T, T> {
    return Pair(b, a)
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testSwapInts() {
        Assert.assertEquals(Pair(2, 1), swap(1, 2))
    }

    @Test
    fun testSwapStrings() {
        Assert.assertEquals(Pair("Blue", "Red"), swap("Red", "Blue"))
    }

    @Test
    fun testSwapDoubles() {
        val result = swap(3.14, 2.72)
        Assert.assertEquals(2.72, result.first, 0.001)
        Assert.assertEquals(3.14, result.second, 0.001)
    }

    @Test
    fun testSwapSameValues() {
        Assert.assertEquals(Pair(42, 42), swap(42, 42))
    }
}
